<?php
namespace Database\Seeders; use App\Models\{Site,Category,Artist}; use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder { public function run():void{ $s=Site::firstOrCreate(['name'=>'Back Then Stories'],['domain'=>null,'tagline'=>'The music, stars & moments we never forgot','active'=>true]); foreach(['Music','Celebrities','Behind The Song','Nostalgia','TV & Film'] as $n)Category::firstOrCreate(['name'=>$n],['slug'=>\Illuminate\Support\Str::slug($n)]); foreach(['Elvis Presley','Bee Gees','Marvin Gaye','Dolly Parton'] as $n)Artist::firstOrCreate(['name'=>$n],['slug'=>\Illuminate\Support\Str::slug($n)]); foreach(['banner_top'=>'Top banner','banner_mid'=>'Middle banner','banner_bot'=>'Bottom banner','anchor'=>'Anchor','interstitial'=>'Interstitial','rewarded'=>'Rewarded'] as $k=>$l)\App\Models\AdSlot::firstOrCreate(['site_id'=>$s->id,'key'=>$k],['label'=>$l,'type'=>in_array($k,['anchor','interstitial','rewarded'])?$k:'display','enabled'=>false]); } }
